/**
 * Video content.
 *
 * `explainers` are ORIGINAL animated motion graphics generated by `npm run videos` from ./video-src (no stock footage,
 * no client footage, no audio). They are labelled as illustrations on the site.
 *
 * `embeds` is for REAL videos you record later (founder intro, client stories, project walkthroughs).
 * It is empty on purpose. Add one and a "From us" row appears; embeds load only after the visitor clicks play, so no
 * third-party cookies or scripts run until then.
 */
export type Explainer = {
  slug: string;
  title: string;
  description: string;
  seconds: number;
  /** Text alternative for people who can't watch the animation */
  transcript: string[];
};

