export type Embed = {
  provider: "youtube" | "vimeo";
  /** The video ID only, e.g. "dQw4w9WgXcQ" (YouTube) or "76979871" (Vimeo) */
  id: string;
  title: string;
  description: string;
  /** Optional thumbnail you host yourself, e.g. "/videos/founder-intro.jpg". Without it a plain panel is shown, so nothing loads from YouTube/Vimeo before the click. */
  poster?: string;
  transcript?: string[];
};

export const embeds: Embed[] = [];

export const VIDEO_UPLOAD_DATE = "2026-10-29";
export const fmtDuration = (s: number) => `0:${String(s).padStart(2, "0")}`;
export const isoDuration = (s: number) => `PT${s}S`;

/** IDs are interpolated into an iframe URL, so only accept the characters those providers actually use. */
export const safeEmbedId = (e: Embed) => (e.provider === "youtube" ? /^[\w-]{6,20}$/.test(e.id) : /^\d{4,12}$/.test(e.id));
